import re


def expand_slots(spec: str) -> list[str]:
    if not spec or not spec.strip():
        return []

    slot_pattern = re.compile(r'^([A-Z])([1-9]|[1-9][0-9])$')
    tokens = spec.split(',')
    result: list[str] = []

    for token in tokens:
        token = token.strip()
        if not token:
            raise ValueError("Empty token in spec")

        removal = False
        if token.startswith('!'):
            removal = True
            token = token[1:]

        if '-' in token:
            parts = token.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid range token: {token}")
            m1 = slot_pattern.match(parts[0])
            m2 = slot_pattern.match(parts[1])
            if not m1 or not m2:
                raise ValueError(f"Invalid slot in range: {token}")
            letter = m1.group(1)
            if m2.group(1) != letter:
                raise ValueError(f"Range endpoints must share the same letter: {token}")
            num1 = int(m1.group(2))
            num2 = int(m2.group(2))
            if num1 >= num2:
                slots = [f"{letter}{n}" for n in range(num1, num2 - 1, -1)]
            else:
                slots = [f"{letter}{n}" for n in range(num1, num2 + 1)]
        else:
            m = slot_pattern.match(token)
            if not m:
                raise ValueError(f"Invalid slot token: {token}")
            slots = [token]

        if removal:
            for s in slots:
                if s in result:
                    result.remove(s)
        else:
            for s in slots:
                if s not in result:
                    result.append(s)

    return result
