def top_spenders(events: list[dict], k: int) -> list[tuple[str, int]]:
    if k == 0:
        return []

    # Sort events by (ts, original index) to handle ties stably
    indexed = list(enumerate(events))
    indexed.sort(key=lambda x: (x[1]["ts"], x[0]))

    # Track orders: order_id -> {"customer", "amount", "cancelled", "buy_ts"}
    orders: dict[str, dict] = {}

    for _, ev in indexed:
        order_id = ev["order"]
        etype = ev["type"]

        if etype == "buy":
            if order_id not in orders:
                orders[order_id] = {
                    "customer": ev["customer"],
                    "amount": ev["cents"],
                    "cancelled": False,
                    "buy_ts": ev["ts"],
                }
            # else: duplicate buy, ignore

        elif etype == "refund":
            if order_id in orders and not orders[order_id]["cancelled"]:
                orders[order_id]["amount"] = max(0, orders[order_id]["amount"] - ev["cents"])
            # else: order doesn't exist or is cancelled, ignore

        elif etype == "cancel":
            if order_id in orders:
                orders[order_id]["amount"] = 0
                orders[order_id]["cancelled"] = True
            # else: order doesn't exist, ignore

    # Accumulate per-customer totals and track earliest accepted buy timestamp
    customer_totals: dict[str, int] = {}
    customer_earliest_buy: dict[str, int] = {}

    for info in orders.values():
        cust = info["customer"]
        customer_totals[cust] = customer_totals.get(cust, 0) + info["amount"]
        if cust not in customer_earliest_buy or info["buy_ts"] < customer_earliest_buy[cust]:
            customer_earliest_buy[cust] = info["buy_ts"]

    # Filter out zero-total customers and sort
    ranked = [
        (cust, total)
        for cust, total in customer_totals.items()
        if total > 0
    ]
    ranked.sort(key=lambda x: (-x[1], customer_earliest_buy[x[0]], x[0]))

    return ranked[:k]
