import re


def parse_stanza(text: str) -> dict:
    result = {}
    current_section = None  # None means no section header seen yet

    for line in text.split("\n"):
        # Step 1: Strip comments (scan left to right, toggle on ")
        in_quotes = False
        i = 0
        while i < len(line):
            if line[i] == '"':
                in_quotes = not in_quotes
            elif line[i] == '#' and not in_quotes:
                line = line[:i]
                break
            i += 1

        # Step 2: Strip whitespace; skip if empty
        line = line.strip()
        if not line:
            continue

        # Step 3: Section header
        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            if not name:
                raise ValueError("Empty section name")
            if name not in result:
                result[name] = {}
            current_section = name
            continue

        # Step 4: Entry (must contain '=')
        if '=' not in line:
            raise ValueError(f"Line does not contain '=': {line}")

        key, _, raw_value = line.partition('=')
        key = key.strip()
        if not key:
            raise ValueError("Empty key")

        raw_value = raw_value.strip()

        # Step 5: Entries before any header go to ""
        if current_section is None:
            current_section = ""

        # Step 6: Convert and assign (later replaces earlier)
        result[current_section][key] = _convert_value(raw_value)

    # Remove "" section if it ended up with no entries
    if "" in result and not result[""]:
        del result[""]

    return result


def _convert_value(raw: str):
    # Rule a: quoted string (length >= 2, starts and ends with ")
    if len(raw) >= 2 and raw[0] == '"' and raw[-1] == '"':
        return raw[1:-1]

    # Rule b: list (contains |)
    if '|' in raw:
        parts = raw.split('|')
        return [_convert_scalar(p.strip()) for p in parts]

    # Rule c: scalar
    return _convert_scalar(raw)


def _convert_scalar(s: str):
    if re.fullmatch(r'-?\d+', s):
        return int(s)
    if s == 'yes':
        return True
    if s == 'no':
        return False
    return s
