def run_tally(program: str, max_steps: int) -> tuple[str, list[int]]:
    tokens = program.split()
    n = len(tokens)
    stack: list[int] = []
    output: list[int] = []
    pc = 0
    executed = 0

    while True:
        if pc == n:
            return ("done", output)
        if executed == max_steps:
            return ("limit", output)

        token = tokens[pc]

        if token in ("dup", "drop", "swap", "add", "sub", "mul", "out"):
            if token == "dup":
                if len(stack) < 1:
                    return ("fault", output)
                stack.append(stack[-1])
            elif token == "drop":
                if len(stack) < 1:
                    return ("fault", output)
                stack.pop()
            elif token == "swap":
                if len(stack) < 2:
                    return ("fault", output)
                stack[-1], stack[-2] = stack[-2], stack[-1]
            elif token == "add":
                if len(stack) < 2:
                    return ("fault", output)
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif token == "sub":
                if len(stack) < 2:
                    return ("fault", output)
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            elif token == "mul":
                if len(stack) < 2:
                    return ("fault", output)
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif token == "out":
                if len(stack) < 1:
                    return ("fault", output)
                output.append(stack.pop())
            pc += 1

        elif token.startswith("jmp:"):
            k_str = token[4:]
            if not _is_int(k_str):
                return ("fault", output)
            k = int(k_str)
            target = pc + k
            if target < 0 or target > n:
                return ("fault", output)
            pc = target

        elif token.startswith("jz:"):
            k_str = token[3:]
            if not _is_int(k_str):
                return ("fault", output)
            k = int(k_str)
            if len(stack) < 1:
                return ("fault", output)
            val = stack.pop()
            if val == 0:
                target = pc + k
                if target < 0 or target > n:
                    return ("fault", output)
                pc = target
            else:
                pc += 1

        else:
            if _is_int(token):
                stack.append(int(token))
                pc += 1
            else:
                return ("fault", output)

        executed += 1


def _is_int(s: str) -> bool:
    if not s:
        return False
    if s[0] == '-':
        s = s[1:]
    if not s:
        return False
    return s.isdigit()
