def plan_rounds(deps: dict, capacity: int) -> list[list[str]]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")

    # Validate all prerequisites are keys in deps
    for task, prereqs in deps.items():
        for p in prereqs:
            if p not in deps:
                raise ValueError(f"Prerequisite '{p}' not found in deps")

    # Compute fixed number of direct dependents for each task
    dependents = {task: 0 for task in deps}
    for task, prereqs in deps.items():
        for p in prereqs:
            dependents[p] += 1

    completed = set()
    rounds = []

    while len(completed) < len(deps):
        # Find ready tasks: not yet run, all prereqs in earlier rounds
        ready = [
            task for task in deps
            if task not in completed and all(p in completed for p in deps[task])
        ]

        if not ready:
            raise ValueError("Dependency cycle detected")

        # Sort: most direct dependents first, ties broken by name ascending
        ready.sort(key=lambda t: (-dependents[t], t))

        # Schedule up to `capacity` tasks this round
        round_tasks = ready[:capacity]
        rounds.append(round_tasks)
        completed.update(round_tasks)

    return rounds
