def kth_badge(length: int, k: int) -> str:
    if length < 1:
        raise ValueError("length must be >= 1")
    if k < 1:
        raise ValueError("k must be >= 1")

    letters = ['A', 'B', 'C', 'D']

    # Precompute f[rem][c] = number of valid completions of `rem` more
    # characters given that the last placed character is c (0=A,1=B,2=C,3=D).
    # f[0][c] = 1 (nothing left to place)
    # f[rem][A] = f[rem-1][B] + f[rem-1][C]       (after A, next can be B or C; not A (adjacent), not D (AD forbidden))
    # f[rem][B] = f[rem-1][A] + f[rem-1][C] + f[rem-1][D]
    # f[rem][C] = f[rem-1][A] + f[rem-1][B] + f[rem-1][D]
    # f[rem][D] = f[rem-1][A] + f[rem-1][B] + f[rem-1][C]

    f = [[0] * 4 for _ in range(length)]
    for c in range(4):
        f[0][c] = 1
    for rem in range(1, length):
        f[rem][0] = f[rem - 1][1] + f[rem - 1][2]
        f[rem][1] = f[rem - 1][0] + f[rem - 1][2] + f[rem - 1][3]
        f[rem][2] = f[rem - 1][0] + f[rem - 1][1] + f[rem - 1][3]
        f[rem][3] = f[rem - 1][0] + f[rem - 1][1] + f[rem - 1][2]

    total = sum(f[length - 1])
    if k > total:
        raise ValueError(
            f"k={k} exceeds the number of valid badges of length {length} (which is {total})"
        )

    result = []
    prev = -1  # no previous character

    for i in range(length):
        remaining = length - 1 - i
        for c_idx, c in enumerate(letters):
            # Validate against previous character
            if prev != -1:
                if c_idx == prev:
                    continue  # no two adjacent letters equal
                if prev == 0 and c_idx == 3:
                    continue  # "AD" forbidden
            count = f[remaining][c_idx]
            if k <= count:
                result.append(c)
                prev = c_idx
                break
            else:
                k -= count

    return ''.join(result)
