class BulkCache:
    def __init__(self, capacity: int):
        self._capacity = capacity
        self._store = {}   # key -> (value, size)
        self._order = []   # keys in insertion order (oldest first)
        self._total = 0

    def put(self, key, value, size: int) -> bool:
        if size > self._capacity:
            return False

        if key in self._store:
            old_size = self._store[key][1]
            self._total -= old_size
            self._store[key] = (value, size)
            self._total += size
        else:
            self._store[key] = (value, size)
            self._order.append(key)
            self._total += size

        # Evict while total exceeds capacity
        while self._total > self._capacity:
            best_key = None
            best_size = -1
            for k in self._order:
                if k == key:
                    continue
                sz = self._store[k][1]
                if sz > best_size:
                    best_size = sz
                    best_key = k
            # best_key is guaranteed to exist here (see reasoning above)
            self._total -= best_size
            del self._store[best_key]
            self._order.remove(best_key)

        return True

    def get(self, key, default=None):
        if key in self._store:
            return self._store[key][0]
        return default

    def keys(self) -> list:
        return list(self._order)

    def used(self) -> int:
        return self._total
