class HoldDesk:
    def __init__(self, stock: dict, ttl: int):
        self.stock = dict(stock)  # copy so the caller's dict is not modified
        self.ttl = ttl
        self.holds = {}  # hold_id -> (item, qty, t0, status)
        self.next_id = 1

    def _is_active(self, hold_id: int, t: int) -> bool:
        if hold_id not in self.holds:
            return False
        item, qty, t0, status = self.holds[hold_id]
        return status == "active" and t < t0 + self.ttl

    def hold(self, item: str, qty: int, t: int):
        if item not in self.stock:
            return None
        if self.available(item, t) < qty:
            return None
        hold_id = self.next_id
        self.next_id += 1
        self.holds[hold_id] = (item, qty, t, "active")
        return hold_id

    def confirm(self, hold_id: int, t: int) -> bool:
        if not self._is_active(hold_id, t):
            return False
        item, qty, t0, _ = self.holds[hold_id]
        self.stock[item] -= qty
        self.holds[hold_id] = (item, qty, t0, "confirmed")
        return True

    def release(self, hold_id: int, t: int) -> bool:
        if not self._is_active(hold_id, t):
            return False
        item, qty, t0, _ = self.holds[hold_id]
        self.holds[hold_id] = (item, qty, t0, "released")
        return True

    def available(self, item: str, t: int) -> int:
        if item not in self.stock:
            return 0
        result = self.stock[item]
        for hold_id, (h_item, h_qty, h_t0, h_status) in self.holds.items():
            if h_item == item and h_status == "active" and t < h_t0 + self.ttl:
                result -= h_qty
        return result
