def mask_account_numbers(text: str) -> str:
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i].isdigit():
            # Collect the full digit run starting at i
            j = i + 1
            while j < n:
                if text[j].isdigit():
                    j += 1
                elif text[j] in (' ', '-') and j + 1 < n and text[j + 1].isdigit():
                    j += 2
                else:
                    break

            run = text[i:j]
            digit_count = sum(1 for c in run if c.isdigit())

            if digit_count >= 8:
                # Mask all digits except the last four
                masked = []
                seen = 0
                to_mask = digit_count - 4
                for c in run:
                    if c.isdigit():
                        seen += 1
                        masked.append('*' if seen <= to_mask else c)
                    else:
                        masked.append(c)
                result.append(''.join(masked))
            else:
                result.append(run)

            i = j
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)
