from datetime import datetime, timedelta


def shift_working_days(start: str, n: int, holidays: list[str], rest_days: list[int]) -> str:
    if len(set(rest_days)) == 7:
        raise ValueError("rest_days contains all seven weekdays")

    holiday_set = set(holidays)
    rest_set = set(rest_days)
    start_date = datetime.strptime(start, "%Y-%m-%d").date()

    def is_working_day(d: datetime.date) -> bool:
        return d.weekday() not in rest_set and d.strftime("%Y-%m-%d") not in holiday_set

    if n == 0:
        if is_working_day(start_date):
            return start
        d = start_date + timedelta(days=1)
        while not is_working_day(d):
            d += timedelta(days=1)
        return d.strftime("%Y-%m-%d")

    elif n > 0:
        d = start_date + timedelta(days=1)
        count = 0
        while True:
            if is_working_day(d):
                count += 1
                if count == n:
                    return d.strftime("%Y-%m-%d")
            d += timedelta(days=1)

    else:
        d = start_date - timedelta(days=1)
        count = 0
        while True:
            if is_working_day(d):
                count += 1
                if count == -n:
                    return d.strftime("%Y-%m-%d")
            d -= timedelta(days=1)
