def league_table(matches: list[tuple[str, int, str, int]]) -> list[tuple[int, str, int, int, int]]:
    if not matches:
        return []

    teams: dict[str, list[int]] = {}

    for home, hg, away, ag in matches:
        if home == away:
            raise ValueError("Same team on both sides of a match")

        for t in (home, away):
            if t not in teams:
                teams[t] = [0, 0, 0]  # points, goals_for, goals_against

        teams[home][1] += hg
        teams[home][2] += ag
        teams[away][1] += ag
        teams[away][2] += hg

        if hg > ag:
            teams[home][0] += 3
        elif hg == ag:
            teams[home][0] += 1
            teams[away][0] += 1
        else:
            teams[away][0] += 3

    entries = []
    for team, (pts, gf, ga) in teams.items():
        entries.append((team, pts, gf - ga, gf))

    entries.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

    result = []
    for i, (team, pts, gd, gf) in enumerate(entries):
        rank = 1
        for j in range(i):
            if (entries[j][1], entries[j][2], entries[j][3]) > (pts, gd, gf):
                rank += 1
            else:
                break
        result.append((rank, team, pts, gd, gf))

    return result
