def runoff_winner(ballots: list[list[str]]) -> tuple[str, list[str]]:
    # Collect all candidates
    candidates = set()
    for ballot in ballots:
        for c in ballot:
            candidates.add(c)

    if not candidates:
        raise ValueError("No candidates")

    eliminated = []
    eliminated_set = set()
    round1_votes = {}
    round_num = 0

    while True:
        round_num += 1
        # Count votes for this round
        remaining = [c for c in candidates if c not in eliminated_set]
        votes = {c: 0 for c in remaining}
        non_exhausted = 0

        for ballot in ballots:
            for c in ballot:
                if c not in eliminated_set:
                    votes[c] += 1
                    non_exhausted += 1
                    break
            # else: ballot is exhausted

        if round_num == 1:
            round1_votes = dict(votes)

        # Step 2: check for majority (> half of non-exhausted)
        if non_exhausted > 0:
            for c in remaining:
                if votes[c] * 2 > non_exhausted:
                    return (c, eliminated)

        # Step 3: only one candidate left
        if len(remaining) == 1:
            return (remaining[0], eliminated)

        # Step 4: eliminate a candidate
        min_votes = min(votes[c] for c in remaining)
        tied = [c for c in remaining if votes[c] == min_votes]

        if len(tied) == 1:
            to_eliminate = tied[0]
        else:
            # Tie-break: fewest votes in round 1
            min_r1 = min(round1_votes[c] for c in tied)
            tied2 = [c for c in tied if round1_votes[c] == min_r1]
            if len(tied2) == 1:
                to_eliminate = tied2[0]
            else:
                # Tie-break: alphabetically last
                to_eliminate = max(tied2)

        eliminated_set.add(to_eliminate)
        eliminated.append(to_eliminate)
