def grow_moss(cells: str, steps: int) -> str:
    valid = set('.oO')
    for c in cells:
        if c not in valid:
            raise ValueError(f"Invalid character: {c!r}")

    if steps == 0 or not cells:
        return cells

    def step(s):
        n = len(s)
        result = []
        for i in range(n):
            left = s[i - 1] if i > 0 else '.'
            right = s[i + 1] if i < n - 1 else '.'
            live = sum(1 for nb in (left, right) if nb in ('o', 'O'))
            c = s[i]
            if c == '.':
                result.append('o' if live == 1 else '.')
            elif c == 'o':
                if live == 2:
                    result.append('O')
                elif live == 0:
                    result.append('.')
                else:
                    result.append('o')
            else:  # c == 'O'
                if live == 2:
                    result.append('.')
                elif live == 0:
                    result.append('o')
                else:
                    result.append('O')
        return ''.join(result)

    # Simulate until a cycle is detected (state space is at most 3^12)
    states = [cells]
    seen = {cells: 0}

    while True:
        new_state = step(states[-1])
        if new_state in seen:
            cycle_start = seen[new_state]
            cycle_len = len(states) - cycle_start
            if steps < len(states):
                return states[steps]
            idx = cycle_start + (steps - cycle_start) % cycle_len
            return states[idx]
        seen[new_state] = len(states)
        states.append(new_state)
