def fill_template(template: str, values: dict) -> str:
    result = []
    i = 0
    n = len(template)

    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
            else:
                close = template.find('}', i + 1)
                if close == -1:
                    raise ValueError("Unclosed field: no '}' found")
                content = template[i + 1:close]
                if '{' in content:
                    raise ValueError("Nested '{' inside field")
                result.append(_process_field(content, values))
                i = close + 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
            else:
                raise ValueError("Unmatched '}' not part of '}}'")
        else:
            result.append(c)
            i += 1

    return ''.join(result)


def _process_field(content: str, values: dict) -> str:
    parts = content.split('|')
    name = parts[0]
    if name == '':
        raise ValueError("Empty field name")

    filters = []
    for piece in parts[1:]:
        filters.append(_parse_filter(piece))

    if name in values:
        val = str(values[name])
        for f in filters:
            val = _apply_filter(f, val)
        return val
    else:
        return f"<{name}?>"


def _parse_filter(piece: str):
    if piece == '':
        raise ValueError("Empty filter")

    if ':' in piece:
        fname, _, arg = piece.partition(':')
        if fname in ('upper', 'lower', 'rev'):
            raise ValueError(f"Filter '{fname}' does not take an argument")
        elif fname in ('pad', 'cut'):
            if not _valid_int(arg):
                raise ValueError(f"Filter '{fname}' requires a non-negative integer argument")
            return (fname, int(arg))
        else:
            raise ValueError(f"Unknown filter: '{fname}'")
    else:
        if piece in ('upper', 'lower', 'rev'):
            return (piece, None)
        elif piece in ('pad', 'cut'):
            raise ValueError(f"Filter '{piece}' requires a non-negative integer argument")
        else:
            raise ValueError(f"Unknown filter: '{piece}'")


def _valid_int(s: str) -> bool:
    if not s:
        return False
    return all(c in '0123456789' for c in s)


def _apply_filter(f, val: str) -> str:
    name, arg = f
    if name == 'upper':
        return val.upper()
    elif name == 'lower':
        return val.lower()
    elif name == 'rev':
        return val[::-1]
    elif name == 'pad':
        if len(val) < arg:
            return val + '.' * (arg - len(val))
        return val
    elif name == 'cut':
        return val[:arg]
