import heapq


class TickScheduler:
    def __init__(self):
        self._time = 0
        self._tasks = {}  # name -> (next_firing_time, every, add_order)
        self._seq = 0

    def add(self, name: str, at: int, every=None):
        if at < self._time:
            raise ValueError(f"at={at} is earlier than current time {self._time}")
        self._seq += 1
        self._tasks[name] = (at, every, self._seq)

    def cancel(self, name: str) -> bool:
        if name in self._tasks:
            del self._tasks[name]
            return True
        return False

    def run_until(self, t: int) -> list[tuple[int, str]]:
        if t < self._time:
            raise ValueError(f"t={t} is earlier than current time {self._time}")

        heap = []
        for name, (next_time, every, order) in self._tasks.items():
            if next_time <= t:
                heapq.heappush(heap, (next_time, order, name))

        result = []
        while heap:
            fire_time, order, name = heapq.heappop(heap)
            if fire_time > t:
                break

            result.append((fire_time, name))

            _, every, task_order = self._tasks[name]

            if every is not None:
                new_time = fire_time + every
                self._tasks[name] = (new_time, every, task_order)
                if new_time <= t:
                    heapq.heappush(heap, (new_time, task_order, name))
            else:
                del self._tasks[name]

        self._time = t
        return result

    def pending(self) -> list[str]:
        return sorted(self._tasks.keys())
