def dock_title(name: str) -> str:
    words = name.split()
    if not words:
        return ""

    small_words = {"a", "an", "and", "of", "the", "in", "on", "to"}

    def transform_part(part: str, is_first: bool, is_last: bool) -> str:
        if not part:
            return part
        # Rule a: contains at least one digit → upper case
        if any(c.isdigit() for c in part):
            return part.upper()
        # Rule b: 2-3 chars, all uppercase letters A-Z → unchanged
        if 2 <= len(part) <= 3 and part.isalpha() and part.isupper():
            return part
        # Rule c: small word, not in first/last position → lower case
        if part.lower() in small_words and not is_first and not is_last:
            return part.lower()
        # Rule d: capitalize first, lowercase rest
        return part[0].upper() + part[1:].lower()

    result_words = []
    for i, word in enumerate(words):
        parts = word.split('-')
        transformed = []
        for j, part in enumerate(parts):
            is_first = (i == 0 and j == 0)
            is_last = (i == len(words) - 1 and j == len(parts) - 1)
            transformed.append(transform_part(part, is_first, is_last))
        result_words.append('-'.join(transformed))

    return ' '.join(result_words)
