def curve_grades(scores: dict) -> dict:
    if not scores:
        return {}

    present = {name: score for name, score in scores.items() if score is not None}
    n = len(present)

    # Compute limits using integer arithmetic (ceiling via (a + b - 1) // b)
    limit_a = (n + 4) // 5       # ceil(0.2 * n) = ceil(n / 5)
    limit_b = (n + 1) // 2       # ceil(0.5 * n) = ceil(n / 2)
    limit_c = (4 * n + 4) // 5   # ceil(0.8 * n) = ceil(4n / 5)

    result = {}
    for name, score in scores.items():
        if score is None:
            result[name] = "X"
        else:
            rank = 1 + sum(1 for s in present.values() if s > score)
            if rank <= limit_a:
                result[name] = "A"
            elif rank <= limit_b:
                result[name] = "B"
            elif rank <= limit_c:
                result[name] = "C"
            else:
                result[name] = "D"

    return result
